// 3D menu backdrop: an interactive "Explore India" board with city pins placed by their real latitude /
// longitude (equirectangular), plus a garage turntable used to preview vehicles. Only cities whose data has
// been generated by the OSM pipeline (StreamingAssets/Cities/<id>/index.json) are playable.
// Note: no national boundary is drawn - an official boundary layer (Survey of India) should be used for that.
using System.Collections.Generic;
using Shehar.City;
using Shehar.Vehicles;
using UnityEngine;

namespace Shehar
{
    public sealed class CityInfo
    {
        public string Id, Name, State, Blurb;
        public double Lat, Lon;          // approximate city-centre coordinates (WGS84)
        public bool Available { get { return CityWorld.CityAvailable(Id); } }
    }

    public static class CityRegistry
    {
        public static readonly List<CityInfo> Cities = new List<CityInfo>
        {
            new CityInfo { Id = "pune", Name = "Pune", State = "Maharashtra", Lat = 18.5204, Lon = 73.8567, Blurb = "Shivajinagar, Deccan, FC Road, JM Road, the Peths, Swargate and Pune Station - built from OpenStreetMap." },
            new CityInfo { Id = "mumbai", Name = "Mumbai", State = "Maharashtra", Lat = 19.0760, Lon = 72.8777, Blurb = "Marine Drive, Bandra-Worli Sea Link, Colaba, Dadar, Andheri, Juhu." },
            new CityInfo { Id = "delhi", Name = "Delhi", State = "NCT of Delhi", Lat = 28.6139, Lon = 77.2090, Blurb = "Connaught Place, India Gate, Chandni Chowk." },
            new CityInfo { Id = "bengaluru", Name = "Bengaluru", State = "Karnataka", Lat = 12.9716, Lon = 77.5946, Blurb = "MG Road, Koramangala, Indiranagar." },
            new CityInfo { Id = "hyderabad", Name = "Hyderabad", State = "Telangana", Lat = 17.3850, Lon = 78.4867, Blurb = "Charminar, HITEC City, Hussain Sagar." },
            new CityInfo { Id = "chennai", Name = "Chennai", State = "Tamil Nadu", Lat = 13.0827, Lon = 80.2707, Blurb = "Marina Beach, T. Nagar, Mylapore." },
            new CityInfo { Id = "kolkata", Name = "Kolkata", State = "West Bengal", Lat = 22.5726, Lon = 88.3639, Blurb = "Howrah Bridge, Park Street, Esplanade." },
            new CityInfo { Id = "jaipur", Name = "Jaipur", State = "Rajasthan", Lat = 26.9124, Lon = 75.7873, Blurb = "Hawa Mahal, MI Road, the walled city." },
            new CityInfo { Id = "goa", Name = "Goa (Panaji)", State = "Goa", Lat = 15.4909, Lon = 73.8278, Blurb = "Panaji, Miramar, the Mandovi riverfront." },
            new CityInfo { Id = "ahmedabad", Name = "Ahmedabad", State = "Gujarat", Lat = 23.0225, Lon = 72.5714, Blurb = "Sabarmati Riverfront, Old City, SG Highway." },
            new CityInfo { Id = "lucknow", Name = "Lucknow", State = "Uttar Pradesh", Lat = 26.8467, Lon = 80.9462, Blurb = "Hazratganj, Bara Imambara, Gomti Nagar." },
        };

        public static CityInfo Get(string id) { foreach (var c in Cities) if (c.Id == id) return c; return null; }
    }

    public sealed class MenuScene : MonoBehaviour
    {
        public static MenuScene Instance { get; private set; }
        public string Hovered, Selected = "pune";
        public bool GarageView;
        readonly Dictionary<string, Transform> pins = new Dictionary<string, Transform>();
        readonly List<TextMesh> labels = new List<TextMesh>();
        Camera cam;
        float orbit;
        Transform turntable;
        GameObject preview;
        string previewId;
        static readonly Vector3 GaragePos = new Vector3(5000, 0, 0);
        const float K = 3.2f; // board units per degree

        public static MenuScene Create(Camera c)
        {
            Materials.Init();
            var go = new GameObject("MenuScene");
            var m = go.AddComponent<MenuScene>();
            m.cam = c;
            m.Build();
            return m;
        }

        void Awake() { Instance = this; }
        void OnDestroy() { if (Instance == this) Instance = null; }

        static Vector3 Board(double lat, double lon) { return new Vector3((float)(lon - 80.0) * K, 0, (float)(lat - 22.0) * K); }

        void Build()
        {
            // board + graticule
            var board = new MeshBuilder();
            board.Quad(new Vector3(-60, 0, -55), new Vector3(-60, 0, 55), new Vector3(60, 0, 55), new Vector3(60, 0, -55), new Color32(14, 22, 44, 255));
            Part("Board", board, Materials.Concrete, false);
            var grid = new MeshBuilder();
            for (int lon = 66; lon <= 98; lon += 2)
            {
                var a = Board(6, lon); var b = Board(38, lon);
                grid.Ribbon(new List<Vector3> { a, b }, lon % 10 == 0 ? 0.08f : 0.04f, 0, 0.01f, new Color32(60, 90, 150, 255), 1e6f);
            }
            for (int lat = 6; lat <= 38; lat += 2)
            {
                var a = Board(lat, 66); var b = Board(lat, 98);
                grid.Ribbon(new List<Vector3> { a, b }, lat % 10 == 0 ? 0.08f : 0.04f, 0, 0.01f, new Color32(60, 90, 150, 255), 1e6f);
            }
            Part("Graticule", grid, Materials.Unlit, false);
            var tropic = new MeshBuilder();
            tropic.Ribbon(new List<Vector3> { Board(23.44, 66), Board(23.44, 98) }, 0.06f, 0, 0.012f, new Color32(255, 153, 51, 255), 0.6f);
            Part("TropicOfCancer", tropic, Materials.Marking, false);
            var t = VehicleFactory.Label(transform, "Tropic of Cancer", Board(23.9, 67.5) + Vector3.up * 0.05f, 0, 0.18f, new Color(1f, 0.6f, 0.2f, 0.8f));
            t.transform.rotation = Quaternion.Euler(90, 0, 0);
            t.anchor = TextAnchor.MiddleLeft;

            foreach (var c in CityRegistry.Cities)
            {
                bool ok = c.Available;
                var pin = new GameObject("Pin_" + c.Id);
                pin.transform.SetParent(transform, false);
                pin.transform.localPosition = Board(c.Lat, c.Lon);
                var mb = new MeshBuilder();
                float h = ok ? 3.2f : 1.6f;
                Color32 col = ok ? new Color32(255, 153, 51, 255) : new Color32(130, 140, 160, 255);
                mb.Cylinder(new Vector3(0, h / 2, 0), Vector3.up, 0.08f, h, 8, col, false);
                mb.Blob(new Vector3(0, h + 0.35f, 0), new Vector3(0.35f, 0.35f, 0.35f), 12, 8, col);
                mb.Disc(new Vector3(0, 0.02f, 0), 0.5f, 18, col);
                var pm = Part("PinMesh", mb, ok ? Materials.SignalAmber : Materials.Concrete, false, pin.transform);
                var sc = pin.AddComponent<SphereCollider>(); sc.radius = 0.9f; sc.center = new Vector3(0, h * 0.6f, 0);
                var lbl = VehicleFactory.Label(pin.transform, c.Name + (ok ? "" : "\n<size=24>coming soon</size>"), new Vector3(0, h + 1.2f, 0), 0, 0.22f, ok ? Color.white : new Color(0.7f, 0.75f, 0.85f));
                lbl.richText = true;
                labels.Add(lbl);
                pins[c.Id] = pin.transform;
            }

            // garage turntable
            var tt = new GameObject("Turntable");
            tt.transform.SetParent(transform, false);
            tt.transform.position = GaragePos;
            var floor = new MeshBuilder();
            floor.Disc(Vector3.zero, 9f, 48, new Color32(40, 42, 48, 255));
            floor.Cylinder(new Vector3(0, -0.05f, 0), Vector3.up, 4.2f, 0.12f, 48, new Color32(70, 72, 80, 255));
            var fp = Part("Floor", floor, Materials.Concrete, false, tt.transform);
            turntable = new GameObject("Spin").transform;
            turntable.SetParent(tt.transform, false);
            var lightGo = new GameObject("GarageLight");
            lightGo.transform.SetParent(tt.transform, false);
            lightGo.transform.localPosition = new Vector3(3, 6, -4);
            var l = lightGo.AddComponent<Light>(); l.type = LightType.Point; l.range = 25; l.intensity = 2.2f; l.color = new Color(1f, 0.92f, 0.8f);

            if (RenderSettings.sun == null)
            {
                var sun = new GameObject("MenuSun").AddComponent<Light>();
                sun.type = LightType.Directional; sun.intensity = 1.0f;
                sun.transform.SetParent(transform, false);
                sun.transform.rotation = Quaternion.Euler(50, -30, 0);
            }
            RenderSettings.fog = false;
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.35f, 0.38f, 0.45f);
            if (Materials.Sky != null)
            {
                RenderSettings.skybox = Materials.Sky;
                Materials.Sky.SetColor("_TopColor", new Color(0.02f, 0.03f, 0.08f));
                Materials.Sky.SetColor("_HorizonColor", new Color(0.12f, 0.1f, 0.18f));
                Materials.Sky.SetColor("_GroundColor", new Color(0.03f, 0.03f, 0.05f));
                Materials.Sky.SetFloat("_Stars", 1f);
                Materials.Sky.SetColor("_SunColor", Color.black);
            }
            Shader.SetGlobalFloat("_SheharNight", 1f);
        }

        GameObject Part(string name, MeshBuilder mb, Material m, bool shadows, Transform parent = null)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent ?? transform, false);
            go.AddComponent<MeshFilter>().sharedMesh = mb.ToMesh(name);
            var r = go.AddComponent<MeshRenderer>();
            r.sharedMaterial = m;
            r.shadowCastingMode = shadows ? UnityEngine.Rendering.ShadowCastingMode.On : UnityEngine.Rendering.ShadowCastingMode.Off;
            return go;
        }

        public void ShowVehicle(string id)
        {
            if (previewId == id && preview != null) return;
            if (preview != null) Destroy(preview);
            previewId = id;
            var spec = VehicleSpec.Get(id);
            preview = VehicleFactory.Build(spec, spec.Palette[0], "MH 12 SH 2026", false);
            preview.transform.SetParent(turntable, false);
            preview.transform.localPosition = Vector3.zero;
            Materials.LightFront.SetColor("_EmissionColor", new Color(1f, 0.97f, 0.85f) * 1.6f);
            var rig = preview.GetComponent<VehicleRig>();
            if (rig.HeadLights != null) rig.HeadLights.sharedMaterial = Materials.LightFront;
        }

        void Update()
        {
            if (cam == null) return;
            float dt = Time.unscaledDeltaTime;
            orbit += dt * 4f;
            if (GarageView)
            {
                turntable.Rotate(0, dt * 25f, 0);
                float L = previewId != null ? VehicleSpec.Get(previewId).Length : 4f;
                Vector3 target = GaragePos + Vector3.up * 0.9f;
                Vector3 p = target + Quaternion.Euler(14, 210, 0) * Vector3.back * (L * 1.25f + 4f);
                cam.transform.position = Vector3.Lerp(cam.transform.position, p, 1 - Mathf.Exp(-dt * 6f));
                cam.transform.rotation = Quaternion.LookRotation(target - cam.transform.position);
                return;
            }
            Vector3 focus = Selected != null && pins.ContainsKey(Selected) ? pins[Selected].position : Vector3.zero;
            focus = Vector3.Lerp(Vector3.zero, focus, 0.55f);
            Vector3 camPos = focus + Quaternion.Euler(52, Mathf.Sin(orbit * 0.05f) * 25f, 0) * Vector3.back * 62f;
            cam.transform.position = Vector3.Lerp(cam.transform.position, camPos, 1 - Mathf.Exp(-dt * 2.5f));
            cam.transform.rotation = Quaternion.Slerp(cam.transform.rotation, Quaternion.LookRotation(focus - cam.transform.position), 1 - Mathf.Exp(-dt * 4f));
            foreach (var l in labels) l.transform.rotation = Quaternion.LookRotation(l.transform.position - cam.transform.position);
            // hover / click on pins
            Hovered = null;
            Ray ray = cam.ScreenPointToRay(Input.mousePosition);
            if (Physics.Raycast(ray, out RaycastHit hit, 500f))
            {
                foreach (var kv in pins) if (hit.transform == kv.Value) { Hovered = kv.Key; break; }
                if (Hovered != null && Input.GetMouseButtonDown(0) && GUIUtility.hotControl == 0) Selected = Hovered;
            }
            foreach (var kv in pins)
            {
                float s = kv.Key == Selected ? 1.35f + Mathf.Sin(Time.unscaledTime * 4f) * 0.08f : kv.Key == Hovered ? 1.2f : 1f;
                kv.Value.localScale = Vector3.one * s;
            }
        }
    }
}
